function rampartSimulate(createStrategy, seed, maxTicks) {
  const rec = arguments.length > 3 ? arguments[3] : null;
  const TNAMES = ["bolt", "cannon", "frost", "lance", "flak"];
  const TT = {
    bolt: { idx: 0, cost: 50, dmg: 26, period: 8, range: 300, splash: 0, slow: 0, pierce: 0, ground: 1, air: 1 },
    cannon: { idx: 1, cost: 90, dmg: 60, period: 24, range: 260, splash: 90, slow: 0, pierce: 0, ground: 1, air: 0 },
    frost: { idx: 2, cost: 70, dmg: 10, period: 12, range: 240, splash: 0, slow: 30, pierce: 0, ground: 1, air: 1 },
    lance: { idx: 3, cost: 120, dmg: 180, period: 36, range: 360, splash: 0, slow: 0, pierce: 1, ground: 1, air: 0 },
    flak: { idx: 4, cost: 80, dmg: 40, period: 10, range: 320, splash: 70, slow: 0, pierce: 0, ground: 0, air: 1 }
  };
  const ET = {
    grunt: { hp: 60, speed: 10, bounty: 4, leak: 1, air: 0 },
    runner: { hp: 40, speed: 20, bounty: 4, leak: 1, air: 0 },
    wisp: { hp: 50, speed: 12, bounty: 6, leak: 2, air: 1 },
    brute: { hp: 150, speed: 6, bounty: 9, leak: 3, air: 0 },
    splitter: { hp: 90, speed: 8, bounty: 6, leak: 2, air: 0 },
    mender: { hp: 70, speed: 8, bounty: 7, leak: 2, air: 0 },
    splitling: { hp: 0, speed: 12, bounty: 1, leak: 1, air: 0 }
  };
  const GEN = [["grunt", 1, 10], ["runner", 2, 4], ["wisp", 3, 3], ["brute", 4, 3], ["splitter", 6, 2], ["mender", 8, 1]];
  function mkRoute(pts) {
    const p = pts.map(function (q) { return [q[0] * 100 + 50, q[1] * 100 + 50]; });
    const cum = [0];
    for (let i = 1; i < p.length; i++) cum.push(cum[i - 1] + Math.abs(p[i][0] - p[i - 1][0]) + Math.abs(p[i][1] - p[i - 1][1]));
    return { p: p, cum: cum, len: cum[cum.length - 1] };
  }
  const ROUTES = [
    mkRoute([[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]]),
    mkRoute([[0, 6], [21, 6], [21, 11], [23, 11]])
  ];
  function setPos(e) {
    const r = ROUTES[e.air]; let d = e.progress;
    if (d >= r.len) { e.x = r.p[r.p.length - 1][0]; e.y = r.p[r.p.length - 1][1]; return; }
    let i = 1; while (r.cum[i] < d) i++;
    const a = r.p[i - 1], b = r.p[i], o = d - r.cum[i - 1];
    e.x = a[0] + (b[0] > a[0] ? o : b[0] < a[0] ? -o : 0);
    e.y = a[1] + (b[1] > a[1] ? o : b[1] < a[1] ? -o : 0);
  }
  const SLOT_TILES = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  const slots = SLOT_TILES.map(function (t, i) { return { slot: i, x: t[0] * 100 + 50, y: t[1] * 100 + 50, turret: null }; });
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  const rng = mulberry32(seed);
  const mArr = [0, 1000];
  function mult(w) { while (mArr.length <= w) mArr.push(Math.floor(mArr[mArr.length - 1] * 108 / 100)); return mArr[w]; }
  function genWave(w) {
    const n = 4 + Math.floor(3 * w / 5), out = [];
    let total = 0;
    for (let i = 0; i < GEN.length; i++) if (GEN[i][1] <= w) total += GEN[i][2];
    for (let k = 0; k < n; k++) {
      let r = rng() % total;
      for (let i = 0; i < GEN.length; i++) {
        if (GEN[i][1] > w) continue;
        if (r < GEN[i][2]) { out.push(GEN[i][0]); break; }
        r -= GEN[i][2];
      }
    }
    return out;
  }
  function view(e) {
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: e.armor, speed: e.speed, slowed: e.slow > 0 ? 1 : 0, remaining: ROUTES[e.air].len - e.progress };
  }
  const strategy = createStrategy();
  const hasTarget = strategy && typeof strategy.target === "function";
  const log = [];
  let gold = 250, baseHp = 10, wave = 0, nextId = 1, fallTick = -1;
  let enemies = [];           // ascending id
  let queue = [];
  const waves = {};
  waves[1] = genWave(1);
  function mkEnemy(type, w, maxHp, progress) {
    const t = ET[type];
    const e = { id: nextId++, type: type, wave: w, hp: maxHp, maxHp: maxHp, progress: progress, age: 0, slow: 0, speed: t.speed, air: t.air, bounty: t.bounty, leak: t.leak,
      armor: type === "grunt" ? Math.floor(w / 4) : type === "brute" ? 6 + w : 0, x: 0, y: 0 };
    setPos(e);
    return e;
  }
  function applyActions(acts) {
    if (!Array.isArray(acts)) return;
    const n = Math.min(32, acts.length);
    for (let i = 0; i < n; i++) {
      const a = acts[i];
      if (!a || typeof a !== "object") continue;
      const s = a.slot;
      if (typeof s !== "number" || s !== Math.floor(s) || s < 0 || s > 15) continue;
      const sl = slots[s];
      if (a.op === "build") {
        if (sl.turret || typeof a.type !== "string" || !Object.prototype.hasOwnProperty.call(TT, a.type)) continue;
        const tt = TT[a.type];
        if (gold < tt.cost) continue;
        gold -= tt.cost;
        sl.turret = { type: a.type, tier: 1, spent: tt.cost, cd: 0, dmg: tt.dmg, range: tt.range };
        log.push([tick, "B", s, tt.idx]);
        if (rec) rec.event(tick, "B", s, tt.idx);
      } else if (a.op === "upgrade") {
        const tu = sl.turret;
        if (!tu || tu.tier >= 3) continue;
        const c = TT[tu.type].cost * tu.tier;
        if (gold < c) continue;
        gold -= c; tu.spent += c; tu.tier++;
        tu.dmg = Math.floor(tu.dmg * 16 / 10); tu.range += 30;
        log.push([tick, "U", s, tu.tier]);
        if (rec) rec.event(tick, "U", s, tu.tier);
      } else if (a.op === "sell") {
        const tu = sl.turret;
        if (!tu) continue;
        gold += Math.floor(tu.spent * 70 / 100);
        if (rec) rec.event(tick, "S", s, TT[tu.type].idx);
        sl.turret = null;
        log.push([tick, "S", s, 0]);
      }
    }
  }
  let tick = 0, fell = false;
  for (tick = 0; tick < maxTicks; tick++) {
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      wave = (tick - 20) / 40 + 1;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      waves[wave + 1] = genWave(wave + 1);
      const state = {
        tick: tick, wave: wave, gold: gold, baseHp: baseHp,
        slots: slots.map(function (sl) { return { slot: sl.slot, x: sl.x, y: sl.y, turret: sl.turret ? { type: sl.turret.type, tier: sl.turret.tier, spent: sl.turret.spent } : null }; }),
        enemies: enemies.map(view),
        nextWave: waves[wave + 1].slice()
      };
      applyActions(strategy.plan(state));
      const comp = waves[wave];
      for (let i = 0; i < comp.length; i++) queue.push({ tick: tick + 4 * i, wave: wave, idx: i, type: comp[i] });
      queue.sort(function (a, b) { return a.tick - b.tick || a.wave - b.wave || a.idx - b.idx; });
      delete waves[wave];
      if (rec) rec.wave(tick, wave, comp, waves[wave + 1]);
    }
    // 2. spawn
    while (queue.length && queue[0].tick <= tick) {
      const q = queue.shift();
      enemies.push(mkEnemy(q.type, q.wave, Math.floor(ET[q.type].hp * mult(q.wave) / 1000), 0));
    }
    // 3. move
    for (let i = 0; i < enemies.length; i++) {
      const e = enemies[i];
      e.progress += e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
      if (e.progress >= ROUTES[e.air].len) {
        baseHp -= e.leak;
        e.dead = true;
        log.push([tick, "L", e.id, baseHp]);
        if (rec) rec.event(tick, "L", e.id, baseHp);
        if (baseHp <= 0) { fell = true; break; }
      } else setPos(e);
    }
    if (fell) {
      log.push([tick, "F", wave, 0]);
      fallTick = tick;
      enemies = enemies.filter(function (e) { return !e.dead; });
      if (rec) { rec.event(tick, "F", wave, 0); rec.frame(tick, enemies, slots, gold, baseHp, wave); }
      break;
    }
    enemies = enemies.filter(function (e) { return !e.dead; });
    // 4. age & heal
    for (let i = 0; i < enemies.length; i++) {
      const e = enemies[i];
      e.age++;
      if (e.type === "mender" && e.age % 20 === 0) {
        for (let j = 0; j < enemies.length; j++) {
          const o = enemies[j], dx = o.x - e.x, dy = o.y - e.y;
          if (dx * dx + dy * dy <= 22500) {
            o.hp += Math.floor(o.maxHp * 8 / 100);
            if (o.hp > o.maxHp) o.hp = o.maxHp;
          }
        }
        if (rec) rec.event(tick, "H", e.id, 0, e.x, e.y);
      }
    }
    // 5. turrets
    for (let s = 0; s < 16; s++) {
      const sl = slots[s], tu = sl.turret;
      if (!tu) continue;
      if (tu.cd > 0) { tu.cd--; if (tu.cd > 0) continue; }
      const tt = TT[tu.type], r2 = tu.range * tu.range, cands = [];
      for (let i = 0; i < enemies.length; i++) {
        const e = enemies[i];
        if (e.air ? !tt.air : !tt.ground) continue;
        const dx = e.x - sl.x, dy = e.y - sl.y;
        if (dx * dx + dy * dy <= r2) cands.push(e);
      }
      if (!cands.length) continue;
      let tgt = null;
      if (hasTarget) {
        const id = strategy.target({ slot: s, type: tu.type, tier: tu.tier, x: sl.x, y: sl.y, range: tu.range }, cands.map(view));
        for (let i = 0; i < cands.length; i++) if (cands[i].id === id) { tgt = cands[i]; break; }
      }
      if (!tgt) {
        let best = Infinity;
        for (let i = 0; i < cands.length; i++) {
          const rem = ROUTES[cands[i].air].len - cands[i].progress;
          if (rem < best) { best = rem; tgt = cands[i]; }
        }
      }
      const tx = tgt.x, ty = tgt.y;
      if (tt.splash > 0) {
        const sp2 = tt.splash * tt.splash;
        for (let i = 0; i < enemies.length; i++) {
          const e = enemies[i];
          if (e.air ? !tt.air : !tt.ground) continue;
          const dx = e.x - tx, dy = e.y - ty;
          if (dx * dx + dy * dy <= sp2) e.hp -= Math.max(1, tu.dmg - e.armor);
        }
      } else {
        tgt.hp -= tt.pierce ? tu.dmg : Math.max(1, tu.dmg - tgt.armor);
        if (tt.slow > 0) tgt.slow = tt.slow;
      }
      tu.cd = tt.period;
      if (rec) rec.event(tick, "X", s, tgt.id, tx, ty, tgt.air);
      let anyDead = false;
      for (let i = 0; i < enemies.length; i++) if (enemies[i].hp <= 0) { anyDead = true; break; }
      if (anyDead) {
        const keep = [], born = [];
        for (let i = 0; i < enemies.length; i++) {
          const e = enemies[i];
          if (e.hp > 0) { keep.push(e); continue; }
          gold += e.bounty;
          log.push([tick, "K", e.id, s]);
          if (rec) rec.event(tick, "K", e.id, s, e.x, e.y, e.air, e.type);
          if (e.type === "splitter") {
            const hp = Math.max(1, Math.floor(e.maxHp / 4));
            for (let k = 0; k < 3; k++) born.push(mkEnemy("splitling", e.wave, hp, e.progress));
          }
        }
        enemies = keep.concat(born);
      }
    }
    // 6. slow timers
    for (let i = 0; i < enemies.length; i++) if (enemies[i].slow > 0) enemies[i].slow--;
    if (rec) rec.frame(tick, enemies, slots, gold, baseHp, wave);
  }
  const endTick = fallTick >= 0 ? fallTick : maxTicks;
  const str = JSON.stringify(log);
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return { score: Math.round((endTick - 20) / 40 * 100) / 100, fallTick: fallTick, log: log, hash: (h >>> 0).toString(16).padStart(8, "0") };
}
