function createStrategy() {
  /*PARAMS*/
  const P = { WM: 3, U: 0.5, D: 0.8, MARGIN: 1.15, H: 2, CAP: 1000, POW: 4, LEAKW: 5, MAXBUY: 8, TYPES: ["bolt", "cannon", "lance", "flak"], MINGAIN: 0, SURPLUS_H: 4 };
  /*ENDPARAMS*/
  const TT = {
    bolt: { cost: 50, dmg: [26, 41, 65], period: 8, range: [300, 330, 360], splash: 0, pierce: 0, ground: 1, air: 1 },
    cannon: { cost: 90, dmg: [60, 96, 153], period: 24, range: [260, 290, 320], splash: 90, pierce: 0, ground: 1, air: 0 },
    frost: { cost: 70, dmg: [10, 16, 25], period: 12, range: [240, 270, 300], splash: 0, pierce: 0, ground: 1, air: 1 },
    lance: { cost: 120, dmg: [180, 288, 460], period: 36, range: [360, 390, 420], splash: 0, pierce: 1, ground: 1, air: 0 },
    flak: { cost: 80, dmg: [40, 64, 102], period: 10, range: [320, 350, 380], splash: 70, pierce: 0, ground: 0, air: 1 }
  };
  const ET = {
    grunt: { hp: 60, speed: 10, leak: 1, air: 0 }, runner: { hp: 40, speed: 20, leak: 1, air: 0 },
    wisp: { hp: 50, speed: 12, leak: 2, air: 1 }, brute: { hp: 150, speed: 6, leak: 3, air: 0 },
    splitter: { hp: 90, speed: 8, leak: 2, air: 0 }, mender: { hp: 70, speed: 8, leak: 2, air: 0 },
    splitling: { hp: 0, speed: 12, leak: 1, air: 0 }
  };
  const GEN = [["grunt", 1, 10], ["runner", 2, 4], ["wisp", 3, 3], ["brute", 4, 3], ["splitter", 6, 2], ["mender", 8, 1]];
  function mkTab(pts) {
    const xs = [], ys = [];
    let x = pts[0][0] * 100 + 50, y = pts[0][1] * 100 + 50;
    xs.push(x); ys.push(y);
    for (let i = 1; i < pts.length; i++) {
      const tx = pts[i][0] * 100 + 50, ty = pts[i][1] * 100 + 50;
      while (x !== tx || y !== ty) { x += tx > x ? 1 : tx < x ? -1 : 0; y += ty > y ? 1 : ty < y ? -1 : 0; xs.push(x); ys.push(y); }
    }
    return { len: xs.length - 1, xs: new Int16Array(xs), ys: new Int16Array(ys) };
  }
  const RT = [mkTab([[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]]), mkTab([[0, 6], [21, 6], [21, 11], [23, 11]])];
  const SL = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]].map(function (t) { return [t[0] * 100 + 50, t[1] * 100 + 50]; });
  const rangeCache = {};
  function rangeTab(slot, range, air) {
    const key = slot * 2000 + range * 2 + air;
    let t = rangeCache[key];
    if (!t) {
      const r = RT[air]; t = new Uint8Array(r.len + 1);
      const sx = SL[slot][0], sy = SL[slot][1], r2 = range * range;
      for (let i = 0; i <= r.len; i++) { const dx = r.xs[i] - sx, dy = r.ys[i] - sy; if (dx * dx + dy * dy <= r2) t[i] = 1; }
      rangeCache[key] = t;
    }
    return t;
  }
  const mArr = [0, 1000];
  function mult(w) { while (mArr.length <= w) mArr.push(Math.floor(mArr[mArr.length - 1] * 108 / 100)); return mArr[w]; }
  function armorOf(type, w) { return type === "grunt" ? Math.floor(w / 4) : type === "brute" ? 6 + w : 0; }
  function synthWave(w) {
    const n = 4 + Math.floor(3 * w / 5), out = [];
    let total = 0;
    for (let i = 0; i < GEN.length; i++) if (GEN[i][1] <= w) total += GEN[i][2];
    for (let k = 0; k < n; k++) {
      const q = (k * 7 + 3) % n;
      let r = Math.floor((q + 0.5) * total / n);
      for (let i = 0; i < GEN.length; i++) {
        if (GEN[i][1] > w) continue;
        if (r < GEN[i][2]) { out.push(GEN[i][0]); break; }
        r -= GEN[i][2];
      }
    }
    return out;
  }
  const wbuf = new Float64Array(4096);
  // choose a target among candidates (shared by the real game and the internal lookahead)
  function pick(tt, dmg, c) {
    const n = c.length;
    if (n === 1) return c[0];
    let best = c[0], bs = -1;
    const WM = P.WM, U = P.U, pierce = tt.pierce;
    for (let i = 0; i < n; i++) {
      const e = c[i];
      let d = pierce ? dmg : dmg - e.armor;
      if (d < 1) d = 1;
      if (d > e.hp) d = e.hp;
      wbuf[i] = e.type === "mender" ? d * WM : d;
    }
    if (tt.splash) {
      const s2 = tt.splash * tt.splash;
      for (let i = 0; i < n; i++) {
        const a = c[i], ax = a.x, ay = a.y;
        let sum = 0;
        for (let j = 0; j < n; j++) {
          const b = c[j], dx = b.x - ax, dy = b.y - ay;
          if (dx * dx + dy * dy <= s2) sum += wbuf[j];
        }
        sum *= 1 + U * (1 - a.remaining / 4600);
        if (sum > bs) { bs = sum; best = a; }
      }
    } else {
      for (let i = 0; i < n; i++) {
        const a = c[i], s = wbuf[i] * (1 + U * (1 - a.remaining / 4600));
        if (s > bs) { bs = s; best = a; }
      }
    }
    return best;
  }
  // internal forward simulation (no frost anywhere, so no slow handling)
  // turrets: [{slot,type,tier}], ens: fresh enemy objects, spawns: [[tick,type,maxHp,armor]] sorted
  function sim(turrets, ens, spawns) {
    const T = [];
    for (let i = 0; i < turrets.length; i++) {
      const tu = turrets[i]; if (!tu) continue;
      const tt = TT[tu.type], rg = tt.range[tu.tier - 1];
      T.push({ tt: tt, dmg: tt.dmg[tu.tier - 1], cd: 0, rg: tt.ground ? rangeTab(i, rg, 0) : null, ra: tt.air ? rangeTab(i, rg, 1) : null });
    }
    let tick = 0, si = 0, J = 0, leak = 0, maxDepth = 0, nid = 100000;
    const POW = P.POW, cands = [];
    while (ens.length || si < spawns.length) {
      while (si < spawns.length && spawns[si][0] <= tick) {
        const s = spawns[si++], et = ET[s[1]];
        ens.push({ id: nid++, type: s[1], hp: s[2], maxHp: s[2], armor: s[3], speed: et.speed, air: et.air, p: 0, x: 0, y: 0, remaining: 0, lk: et.leak });
      }
      let gone = false;
      for (let i = 0; i < ens.length; i++) {
        const e = ens[i], r = RT[e.air];
        e.p += e.speed;
        if (e.p >= r.len) { leak += e.lk; J += e.lk * P.LEAKW; e.hp = -1e18; gone = true; maxDepth = 1; }
        else { e.x = r.xs[e.p]; e.y = r.ys[e.p]; e.remaining = r.len - e.p; }
      }
      if (gone) { const k = []; for (let i = 0; i < ens.length; i++) if (ens[i].hp > -1e17) k.push(ens[i]); ens = k; }
      for (let i = 0; i < ens.length; i++) {
        const e = ens[i];
        if (e.type === "mender" && (e.p / 8) % 20 === 0) {
          for (let j = 0; j < ens.length; j++) {
            const o = ens[j], dx = o.x - e.x, dy = o.y - e.y;
            if (dx * dx + dy * dy <= 22500) { o.hp += Math.floor(o.maxHp * 8 / 100); if (o.hp > o.maxHp) o.hp = o.maxHp; }
          }
        }
      }
      for (let t = 0; t < T.length; t++) {
        const tu = T[t];
        if (tu.cd > 0) { tu.cd--; if (tu.cd > 0) continue; }
        cands.length = 0;
        const rg = tu.rg, ra = tu.ra;
        for (let i = 0; i < ens.length; i++) {
          const e = ens[i];
          if (e.air ? (ra !== null && ra[e.p] === 1) : (rg !== null && rg[e.p] === 1)) cands.push(e);
        }
        if (!cands.length) continue;
        const tt = tu.tt, tg = pick(tt, tu.dmg, cands);
        let dead = false;
        if (tt.splash) {
          const s2 = tt.splash * tt.splash, tx = tg.x, ty = tg.y, air = tg.air;
          for (let i = 0; i < ens.length; i++) {
            const e = ens[i];
            if (e.air !== air) continue;
            const dx = e.x - tx, dy = e.y - ty;
            if (dx * dx + dy * dy <= s2) { const d = tu.dmg - e.armor; e.hp -= d < 1 ? 1 : d; if (e.hp <= 0) dead = true; }
          }
        } else {
          const d = tt.pierce ? tu.dmg : tu.dmg - tg.armor;
          tg.hp -= d < 1 ? 1 : d;
          if (tg.hp <= 0) dead = true;
        }
        tu.cd = tt.period;
        if (dead) {
          const keep = [], born = [];
          for (let i = 0; i < ens.length; i++) {
            const e = ens[i];
            if (e.hp > 0) { keep.push(e); continue; }
            const depth = e.p / RT[e.air].len;
            if (depth > maxDepth) maxDepth = depth;
            J += e.lk * Math.pow(depth, POW);
            if (e.type === "splitter") {
              const hp = Math.max(1, Math.floor(e.maxHp / 4));
              for (let k = 0; k < 3; k++) born.push({ id: nid++, type: "splitling", hp: hp, maxHp: hp, armor: 0, speed: 12, air: 0, p: e.p, x: e.x, y: e.y, remaining: e.remaining, lk: 1 });
            }
          }
          ens = born.length ? keep.concat(born) : keep;
        }
      }
      tick++;
    }
    return { J: J, leak: leak, maxDepth: maxDepth };
  }
  const comps = { 1: ["grunt", "grunt", "grunt", "grunt"] };
  function plan(state) {
    const w = state.wave;
    comps[w + 1] = state.nextWave.slice();
    if (!comps[w]) comps[w] = synthWave(w);
    let gold = state.gold;
    const turrets = state.slots.map(function (s) { return s.turret ? { type: s.turret.type, tier: s.turret.tier } : null; });
    function cheapest() {
      let c = Infinity;
      for (let s = 0; s < 16; s++) {
        const tu = turrets[s];
        if (!tu) c = Math.min(c, 50); else if (tu.tier < 3) c = Math.min(c, TT[tu.type].cost * tu.tier);
      }
      return c;
    }
    if (gold < cheapest()) return [];
    // scenario
    const base = state.enemies.map(function (e) {
      const len = RT[e.air].len;
      return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, armor: e.armor, speed: e.speed, air: e.air, p: len - e.remaining, x: e.x, y: e.y, remaining: e.remaining, lk: ET[e.type] ? ET[e.type].leak : 1 };
    });
    function scenario(H, margin) {
      const sp = [];
      for (let v = Math.max(1, w - 4); v <= w + H; v++) {
        const c = comps[v] || synthWave(v), t0 = (v - w) * 40;
        const mg = v > w ? margin : 1;
        for (let i = 0; i < c.length; i++) {
          const t = t0 + 4 * i;
          if (t < 0) continue;
          sp.push([t, c[i], Math.floor(Math.floor(ET[c[i]].hp * mult(v) / 1000) * mg), armorOf(c[i], v), v, i]);
        }
      }
      sp.sort(function (a, b) { return a[0] - b[0] || a[4] - b[4] || a[5] - b[5]; });
      return sp;
    }
    const spawns = scenario(P.H, P.MARGIN);
    function run(tu, sp) {
      const ens = new Array(base.length);
      for (let i = 0; i < base.length; i++) { const e = base[i]; ens[i] = { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, armor: e.armor, speed: e.speed, air: e.air, p: e.p, x: e.x, y: e.y, remaining: e.remaining, lk: e.lk }; }
      return sim(tu, ens, sp);
    }
    const acts = [];
    let hasAir = false;
    for (let i = 0; i < base.length; i++) if (base[i].air) hasAir = true;
    for (let i = 0; i < spawns.length; i++) if (spawns[i][1] === "wisp") hasAir = true;
    for (let iter = 0; iter < P.MAXBUY && acts.length < 32; iter++) {
      if (gold < cheapest()) break;
      const cur = run(turrets, spawns);
      const safe = cur.leak === 0 && cur.maxDepth <= P.D;
      if (safe && gold <= P.CAP) break;
      const budget = safe ? gold - P.CAP : gold;
      let best = null, bestV = P.MINGAIN;
      for (let s = 0; s < 16; s++) {
        const tu = turrets[s];
        if (!tu) {
          for (let k = 0; k < P.TYPES.length; k++) {
            const ty = P.TYPES[k], c = TT[ty].cost;
            if (c > budget) continue;
            if (ty === "flak" && !hasAir) continue;
            turrets[s] = { type: ty, tier: 1 };
            const r = run(turrets, spawns);
            const v = (cur.J - r.J) / c;
            if (v > bestV) { bestV = v; best = { op: "build", slot: s, type: ty, cost: c }; }
          }
          turrets[s] = null;
        } else if (tu.tier < 3) {
          const c = TT[tu.type].cost * tu.tier;
          if (c > budget) continue;
          tu.tier++;
          const r = run(turrets, spawns);
          tu.tier--;
          const v = (cur.J - r.J) / c;
          if (v > bestV) { bestV = v; best = { op: "upgrade", slot: s, cost: c }; }
        }
      }
      if (!best) break;
      gold -= best.cost;
      if (best.op === "build") { turrets[best.slot] = { type: best.type, tier: 1 }; acts.push({ op: "build", slot: best.slot, type: best.type }); }
      else { turrets[best.slot].tier++; acts.push({ op: "upgrade", slot: best.slot }); }
    }
    return acts;
  }
  function target(turret, candidates) {
    const tt = TT[turret.type];
    if (!tt || !candidates.length) return -1;
    return pick(tt, tt.dmg[turret.tier - 1], candidates).id;
  }
  return { plan: plan, target: target };
}

