  // need upgrades at wave 2 (32-action cap): do builds wave1, upgrades wave 1 too? 16 builds + 16 upg =32, then 16 at wave 2
  const mk2 = () => { const s = cs(); return { plan(st) { const a = []; if (st.wave === 1) { for (let i = 0; i < 16; i++) { const t = NAMES[L[i]]; if (t) { a.push({ op: 'build', slot: i, type: t }); a.push({ op: 'upgrade', slot: i }); } } } else if (st.wave === 2) for (let i = 0; i < 16; i++) a.push({ op: 'upgrade', slot: i }); return a; }, target: s.target }; };
  let tot = 0;
  for (const sd of seeds) tot += simInf(mk2, sd, 12020).score;
  return tot / seeds.length;
}
if (typeof LAYOUTS !== 'undefined') {
  for (const L of LAYOUTS) print(L, evalLayout(L, SEEDS).toFixed(2));
} else {
  let cur = START, cv = evalLayout(cur, SEEDS);
