(function () {
  'use strict';
  const DURATION = 100, TPS = 20, MAXTICKS = 2020;
  const TYPE_IDX = { grunt: 0, runner: 1, wisp: 2, brute: 3, splitter: 4, mender: 5, splitling: 6 };
  const E_SPEED = [10, 20, 12, 6, 8, 8, 12], E_AIR = [0, 0, 1, 0, 0, 0, 0];
  const SLOT_TILES = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  const GROUND_PTS = [[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]];
  const AIR_PTS = [[0, 6], [21, 6], [21, 11], [23, 11]];
  const AIR_Y = 0.8;
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  // visual randomness: seed 42, precomputed table
  const vr = mulberry32(42), RV = new Float32Array(4096);
  for (let i = 0; i < 4096; i++) RV[i] = vr() / 4294967296;
  let rvi = 0;
  function vrand() { rvi = (rvi + 1) & 4095; return RV[rvi]; }
  function rv(n) { return RV[n & 4095]; }

  // ------------------------------------------------------------------ replay
  const frames = [], evShots = [], evKills = [], evHeals = [], evBuilds = [], waveInfo = [], leaks = [];
  const slotShots = []; for (let i = 0; i < 16; i++) slotShots.push([]);
  let fallTick = -1, killN = 0;
  function push(arr, tick, o) { (arr[tick] || (arr[tick] = [])).push(o); }
  const tur = new Array(16).fill(null);
  let turSnap = tur.slice(), turDirty = false;
  const rec = {
    event: function (tick, code, a, b, x, y, air, type) {
      if (code === 'B') { tur[a] = { type: b, tier: 1, bt: tick, ut: -999 }; turDirty = true; push(evBuilds, tick, { k: 0, slot: a, type: b }); }
      else if (code === 'U') { tur[a] = { type: tur[a].type, tier: b, bt: tur[a].bt, ut: tick }; turDirty = true; push(evBuilds, tick, { k: 1, slot: a, type: tur[a].type }); }
      else if (code === 'S') { tur[a] = null; turDirty = true; push(evBuilds, tick, { k: 2, slot: a, type: b }); }
      else if (code === 'X') { const t = tur[a]; push(evShots, tick, { slot: a, type: t.type, x: x / 100, z: y / 100, air: air }); slotShots[a].push({ tick: tick, x: x / 100, z: y / 100 }); }
      else if (code === 'K') push(evKills, tick, { x: x / 100, z: y / 100, air: air, type: TYPE_IDX[type], n: killN++ });
      else if (code === 'H') push(evHeals, tick, { x: x / 100, z: y / 100 });
      else if (code === 'L') leaks.push({ tick: tick, hp: b });
      else if (code === 'F') fallTick = tick;
    },
    wave: function (tick, wave, comp, next) {
      const c = [0, 0, 0, 0, 0, 0];
      if (next) for (let i = 0; i < next.length; i++) c[TYPE_IDX[next[i]]]++;
      waveInfo.push({ tick: tick, wave: wave, next: c });
    },
    frame: function (tick, enemies, slots, gold, baseHp, wave) {
      const n = enemies.length;
      const f = { n: n, id: new Int32Array(n), type: new Uint8Array(n), prog: new Float32Array(n), hp: new Float32Array(n), slow: new Uint8Array(n), gold: gold, hpBase: baseHp, wave: wave, tur: null };
      for (let i = 0; i < n; i++) { const e = enemies[i]; f.id[i] = e.id; f.type[i] = TYPE_IDX[e.type]; f.prog[i] = e.progress; f.hp[i] = Math.max(0, e.hp / e.maxHp); f.slow[i] = e.slow > 0 ? 1 : 0; }
      if (turDirty) { turSnap = tur.slice(); turDirty = false; }
      f.tur = turSnap;
      frames[tick] = f;
    }
  };
  const result = rampartSimulate(createStrategy, 42, MAXTICKS, rec);
  const lastFrame = frames.length - 1;
  const fallTime = fallTick >= 0 ? fallTick / TPS : Infinity;

  // self-check vectors (run for real, reported truthfully)
  const selfCheck = { vectorA: false, vectorB: false };
  try {
    const A = function () { return { plan: function (s) { const a = []; let g = s.gold; for (const sl of s.slots) if (!sl.turret && g >= 50) { a.push({ op: 'build', slot: sl.slot, type: 'bolt' }); g -= 50; } return a; } }; };
    const ra = rampartSimulate(A, 42, 12020);
    selfCheck.vectorA = ra.hash === '82a5353d' && ra.fallTick === 1035 && ra.log.length === 166 && ra.score === 25.38;
    const B = function () { return { plan: function (s) { return s.wave === 1 ? [{ op: 'build', slot: 3, type: 'cannon' }, { op: 'build', slot: 6, type: 'frost' }] : s.wave === 3 ? [{ op: 'upgrade', slot: 3 }, { op: 'build', slot: 12, type: 'flak' }] : s.wave === 6 ? [{ op: 'build', slot: 8, type: 'lance' }, { op: 'sell', slot: 6 }] : []; } }; };
    const rb = rampartSimulate(B, 7, 12020);
    selfCheck.vectorB = rb.hash === '2e8858d7' && rb.fallTick === 457 && rb.log.length === 48 && rb.score === 10.93;
  } catch (err) { /* stays false */ }

  window.BENCH_REPORT = {
    selfCheck: selfCheck,
    strategy: {
      summary: 'Fixed cannon/flak slot template (flak on slots 5,7,10,11,13,15; cannon elsewhere, no frost). At each wave start an embedded forward simulation of the enemies on the board plus the current, next and one synthetic wave scores every affordable build/upgrade by reduction of a penetration-depth cost per gold and buys greedily until the forecast is safe or gold runs out. Targeting maximises effective (splash-summed, overkill-capped) damage weighted toward menders and toward enemies closest to the keep.',
      seedsTested: 20, meanScoreOnTestedSeeds: 46.18
    },
    seed42: { score: result.score, fallTick: result.fallTick },
    systems: { board: 'full', enemiesAndTurrets: 'full', combatVisuals: 'full', fall: 'full', hud: 'full', audio: 'full' },
    simplifications: [
      'Enemies that die between two ticks are extrapolated along their route until the kill tick instead of being interpolated.',
      'Enemies get a small seeded sideways offset on the road so dense columns stay readable (visual only).',
      'Desaturation after the fall is a full-screen pass used only once the fall has happened; the HUD is drawn after it and keeps its colours.',
      'Shot and kill sounds are rate-limited, so not every event is audible.'
    ],
    testedInBrowser: false,
    measuredFps: null
  };

  // ------------------------------------------------------------------ routes (render space, tiles)
  function mkRoute(pts) {
    const p = pts.map(function (q) { return [q[0] + 0.5, q[1] + 0.5]; }), cum = [0];
    for (let i = 1; i < p.length; i++) cum.push(cum[i - 1] + Math.abs(p[i][0] - p[i - 1][0]) + Math.abs(p[i][1] - p[i - 1][1]));
    return { p: p, cum: cum, len: cum[cum.length - 1] };
  }
  const ROUTES = [mkRoute(GROUND_PTS), mkRoute(AIR_PTS)];
  const rp = [0, 0];
  function routePos(air, d) {
    const r = ROUTES[air];
    if (d <= 0) { rp[0] = r.p[0][0] + d; rp[1] = r.p[0][1]; return; }
    if (d >= r.len) { const l = r.p[r.p.length - 1]; rp[0] = l[0]; rp[1] = l[1]; return; }
    let i = 1; while (r.cum[i] < d) i++;
    const a = r.p[i - 1], b = r.p[i], o = d - r.cum[i - 1], L = r.cum[i] - r.cum[i - 1];
    rp[0] = a[0] + (b[0] - a[0]) * o / L; rp[1] = a[1] + (b[1] - a[1]) * o / L;
  }
  function distToGroundPath(x, z) {
    const r = ROUTES[0]; let best = 1e9;
    for (let i = 1; i < r.p.length; i++) {
      const a = r.p[i - 1], b = r.p[i];
      const minx = Math.min(a[0], b[0]), maxx = Math.max(a[0], b[0]), minz = Math.min(a[1], b[1]), maxz = Math.max(a[1], b[1]);
      const dx = x < minx ? minx - x : x > maxx ? x - maxx : 0, dz = z < minz ? minz - z : z > maxz ? z - maxz : 0;
      const d = Math.sqrt(dx * dx + dz * dz); if (d < best) best = d;
    }
    return best;
  }

  // ------------------------------------------------------------------ renderer / scene
  const canvas = document.getElementById('stage');
  const renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.3;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.autoClear = false;
  renderer.setClearColor(0x000000, 0);

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(36, window.innerWidth / window.innerHeight, 0.1, 500);
  const CENTER = new THREE.Vector3(12, 0, 7);
  const camBase = new THREE.Vector3(), camRight = new THREE.Vector3(), camUp = new THREE.Vector3();
  const ELEV = 55 * Math.PI / 180;
  const fitPts = [];
  for (const x of [-0.8, 24.8]) for (const z of [-0.8, 14.8]) { fitPts.push(new THREE.Vector3(x, 0, z)); }
  fitPts.push(new THREE.Vector3(-0.8, 1.3, -0.8), new THREE.Vector3(24.8, 1.3, -0.8), new THREE.Vector3(24.8, 1.6, 12));
  const tv = new THREE.Vector3();
  function fitCamera() {
    const W = window.innerWidth, H = Math.max(200, window.innerHeight);
    camera.aspect = W / H;
    camera.updateProjectionMatrix();
    const lo = -1 + 2 * 98 / H, hi = 0.97;
    let dLo = 5, dHi = 200, shift = 0;
    function measure(d) {
      camera.position.set(CENTER.x, CENTER.y + d * Math.sin(ELEV), CENTER.z + d * Math.cos(ELEV));
      camera.lookAt(CENTER);
      camera.updateMatrixWorld(true);
      camera.matrixWorldInverse.copy(camera.matrixWorld).invert();
      let ymin = 1e9, ymax = -1e9, xmax = 0;
      for (let i = 0; i < fitPts.length; i++) {
        tv.copy(fitPts[i]).applyMatrix4(camera.matrixWorldInverse).applyMatrix4(camera.projectionMatrix);
        if (tv.y < ymin) ymin = tv.y; if (tv.y > ymax) ymax = tv.y; if (Math.abs(tv.x) > xmax) xmax = Math.abs(tv.x);
      }
      return { ok: xmax <= 0.97 && (ymax - ymin) <= (hi - lo), ymin: ymin, ymax: ymax };
    }
    for (let it = 0; it < 40; it++) { const d = (dLo + dHi) / 2; if (measure(d).ok) dHi = d; else dLo = d; }
    const m = measure(dHi);
    shift = (lo + hi) / 2 - (m.ymin + m.ymax) / 2;
    camera.projectionMatrix.elements[9] = -shift;   // vertical lens shift keeps the board clear of the dock
    camera.projectionMatrixInverse.copy(camera.projectionMatrix).invert();
    camBase.copy(camera.position);
    camRight.setFromMatrixColumn(camera.matrixWorld, 0);
    camUp.setFromMatrixColumn(camera.matrixWorld, 1);
  }
  fitCamera();

  // lights (dusk)
  scene.add(new THREE.HemisphereLight(0x6f7fb8, 0x2a2018, 0.75));
  const key = new THREE.DirectionalLight(0xffb878, 2.3);
  key.position.set(12 - 13, 12, 7 + 8);
  key.target.position.copy(CENTER);
  key.castShadow = true;
  key.shadow.mapSize.set(2048, 2048);
  key.shadow.camera.left = -17; key.shadow.camera.right = 17; key.shadow.camera.top = 13; key.shadow.camera.bottom = -13;
  key.shadow.camera.near = 1; key.shadow.camera.far = 50;
  key.shadow.bias = -0.0006; key.shadow.normalBias = 0.03;
  scene.add(key); scene.add(key.target);
  const fill = new THREE.DirectionalLight(0x5070c0, 0.45);
  fill.position.set(30, 10, -6); scene.add(fill);

  // helper canvases stay detached
  function stoneTexture() {
    const c = document.createElement('canvas'); c.width = c.height = 128;
    const g = c.getContext('2d');
    g.fillStyle = '#8a8c94'; g.fillRect(0, 0, 128, 128);
    for (let i = 0; i < 90; i++) {
      const v = 95 + Math.floor(vrand() * 90);
      g.fillStyle = 'rgb(' + v + ',' + v + ',' + (v + 8) + ')';
      const w = 14 + vrand() * 22, h = 10 + vrand() * 16;
      g.fillRect(vrand() * 128 - 8, vrand() * 128 - 8, w, h);
      g.strokeStyle = 'rgba(20,20,26,0.55)'; g.lineWidth = 1.5;
    }
    for (let i = 0; i < 26; i++) { g.strokeStyle = 'rgba(15,15,20,0.5)'; g.beginPath(); const x = vrand() * 128, y = vrand() * 128; g.moveTo(x, y); g.lineTo(x + vrand() * 30 - 15, y + vrand() * 30 - 15); g.stroke(); }
    const t = new THREE.CanvasTexture(c); t.wrapS = t.wrapT = THREE.RepeatWrapping; t.encoding = THREE.sRGBEncoding; return t;
  }
  // terrain
  function vnoise(x, z) {
    const xi = Math.floor(x), zi = Math.floor(z), fx = x - xi, fz = z - zi;
    function h(a, b) { return rv((a * 73 + b * 151 + 1000) | 0); }
    const sx = fx * fx * (3 - 2 * fx), sz = fz * fz * (3 - 2 * fz);
    return (h(xi, zi) * (1 - sx) + h(xi + 1, zi) * sx) * (1 - sz) + (h(xi, zi + 1) * (1 - sx) + h(xi + 1, zi + 1) * sx) * sz;
  }
  const KEEP = { x: 23.5, z: 11.5 };
  (function buildWorld() {
    const g = new THREE.PlaneGeometry(26, 16, 104, 64); g.rotateX(-Math.PI / 2); g.translate(12, 0, 7);
    const pos = g.attributes.position, col = new Float32Array(pos.count * 3);
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i), z = pos.getZ(i);
      let free = Math.min(1, Math.max(0, (distToGroundPath(x, z) - 0.55) / 0.6));
      for (let s = 0; s < 16; s++) { const dx = x - SLOT_TILES[s][0] - 0.5, dz = z - SLOT_TILES[s][1] - 0.5; free = Math.min(free, Math.max(0, (Math.sqrt(dx * dx + dz * dz) - 0.5) / 0.5)); }
      { const dx = x - KEEP.x, dz = z - KEEP.z; free = Math.min(free, Math.max(0, (Math.sqrt(dx * dx + dz * dz) - 1.2) / 0.6)); }
      const n = vnoise(x * 1.7, z * 1.7) * 0.6 + vnoise(x * 4.3 + 9, z * 4.3 + 4) * 0.4;
      const edge = (x < -0.9 || x > 24.9 || z < -0.9 || z > 14.9) ? 0 : 1;
      pos.setY(i, edge * free * (n * 0.34 - 0.04));
      const t = vnoise(x * 0.6 + 30, z * 0.6 + 12), k = 0.75 + n * 0.5;
      col[i * 3] = (0.20 + t * 0.10) * k; col[i * 3 + 1] = (0.24 + t * 0.05) * k; col[i * 3 + 2] = (0.16 + (1 - t) * 0.05) * k;
    }
    g.setAttribute('color', new THREE.BufferAttribute(col, 3));
    g.computeVertexNormals();
    const ground = new THREE.Mesh(g, new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1, metalness: 0, flatShading: true }));
    ground.receiveShadow = true; scene.add(ground);
    const slab = new THREE.Mesh(new THREE.BoxGeometry(26, 0.7, 16), new THREE.MeshStandardMaterial({ color: 0x1b1c20, roughness: 1 }));
    slab.position.set(12, -0.37, 7); scene.add(slab);
    // road
    const tex = stoneTexture();
    const roadMat = new THREE.MeshStandardMaterial({ color: 0x4a4c56, map: tex, roughness: 0.95 });
    const edgeMat = new THREE.MeshStandardMaterial({ color: 0x24252b, roughness: 1 });
    const r = ROUTES[0];
    for (let i = 1; i < r.p.length; i++) {
      const a = r.p[i - 1], b = r.p[i];
      let x0 = Math.min(a[0], b[0]) - 0.42, x1 = Math.max(a[0], b[0]) + 0.42, z0 = Math.min(a[1], b[1]) - 0.42, z1 = Math.max(a[1], b[1]) + 0.42;
